      const viewKey = workspace + '/' + id;
      selection.current = viewKey;
      const prefix = 'marshal/task-rooms/';
      const query = values => '?' + new URLSearchParams(values);
      const url = prefix + 'page' + query({ roomId: id, workspaceId: workspace });
