      const runLabel = { start: '首次运行', retry: '重试运行', reassign: '改派执行', revise: '按意见修正', conversation: '群聊讨论', 'auto-dispatch': '自动派单', backfill: '历史补记' };
      const controlsLocked = busy || visible?.busy === true;
